CustomField.formula:
MOD(FLOOR((DATETIMEVALUE(/* Year Logic */ 
MID(Actual_Departure_Date_Time__c, 7,4) +'-'+ 
/* Month Logic */ 
MID(Actual_Departure_Date_Time__c, 
FIND("/",Actual_Departure_Date_Time__c) + 1, 
FIND("/",Actual_Departure_Date_Time__c, FIND("/",Actual_Departure_Date_Time__c) + 1) - 
FIND("/",Actual_Departure_Date_Time__c) - 1 
)+'-'+    
/* Day Logic */ 
LEFT(Actual_Departure_Date_Time__c, 
FIND("/",Actual_Departure_Date_Time__c) - 1) +' '+ 
/* Time Logic */ 
RIGHT(Actual_Departure_Date_Time__c, 8) )  - DATETIMEVALUE( /* Year Logic */ 
MID(Departure_Date_Time__c, 7,4) +'-'+ 
/* Month Logic */ 
MID(Departure_Date_Time__c, 
FIND("/",Departure_Date_Time__c) + 1, 
FIND("/",Departure_Date_Time__c, FIND("/",Departure_Date_Time__c) + 1) - 
FIND("/",Departure_Date_Time__c) - 1 
)+'-'+    
/* Day Logic */ 
LEFT(Departure_Date_Time__c, 
FIND("/",Departure_Date_Time__c) - 1) +' '+ 
/* Time Logic */ 
RIGHT(Departure_Date_Time__c, 8) ))* 1440),60)
